<script>lucide.createIcons();document.querySelectorAll('[data-modal-open]').forEach(b=>b.onclick=()=>{document.getElementById(b.dataset.modalOpen).classList.add('open');b.closest('details')?.removeAttribute('open')});document.querySelectorAll('[data-modal-close]').forEach(b=>b.onclick=()=>b.closest('.modal').classList.remove('open'));document.querySelectorAll('[data-preference-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.preference-tab,.preference-panel').forEach(e=>e.classList.remove('active'));b.classList.add('active');document.querySelector(`[data-preference-panel="${b.dataset.preferenceTab}"]`).classList.add('active')});document.addEventListener('click',e=>document.querySelectorAll('.user-menu[open]').forEach(menu=>{if(!menu.contains(e.target))menu.removeAttribute('open')}));</script></body></html>
